function parseExportPages(value){
 if(!value.trim())return null;
 const out=new Set();for(const part of value.replace(/，/g,',').split(',')){
 const m=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)throw Error('页码格式应为 1-5,8,12');
 const a=+m[1],b=+(m[2]||m[1]);if(a<1||b<a||b>window.LESSON.slides.length)throw Error('页码应在 1—'+window.LESSON.slides.length+' 之间，且范围从小到大');for(let n=a;n<=b;n++)out.add(n);
 }return [...out].sort((a,b)=>a-b);
}
'use strict';
const L=window.LESSON, $=s=>document.querySelector(s), esc=v=>String(v??'NULL').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const students=[{sid:'2025001',name:'林悦',major:'计算机',grade:2025},{sid:'2025002',name:'周航',major:'数学',grade:2025},{sid:'2025003',name:'张宁',major:'计算机',grade:2025},{sid:'2024004',name:'林悦',major:'软件工程',grade:2024},{sid:'2024005',name:'陈晨',major:'计算机',grade:2024},{sid:'2025006',name:'许安',major:'计算机',grade:2025}];
const courses=[{course_id:'C01',course_name:'数据库原理',credits:4},{course_id:'C02',course_name:'Python程序设计',credits:3},{course_id:'C03',course_name:'数据结构',credits:3},{course_id:'C04',course_name:'大学英语',credits:2},{course_id:'C05',course_name:'体育',credits:1}];
const enrollments=[{sid:'2025001',course_id:'C01',score:88},{sid:'2025001',course_id:'C02',score:92},{sid:'2025002',course_id:'C01',score:76},{sid:'2025003',course_id:'C03',score:null},{sid:'2024004',course_id:'C01',score:85},{sid:'2024005',course_id:'C04',score:0},{sid:'2025006',course_id:'C03',score:90}];
const core=L.slides.filter(s=>!s.extra).length;
const params=new URLSearchParams(location.search);let page=Math.min(L.slides.length-1,Math.max(0,(Number(location.hash.slice(1))||1)-1)), reveal=false, elapsed=0,running=false, started=0;
let channel;try{channel=new BroadcastChannel('classroom-db-lesson01')}catch{}
function table(rows,cols,opts={}){return `<div class="tablewrap"><table><thead><tr>${cols.map(c=>`<th class="${opts.col===c?'mark':''}">${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${opts.mark?.(r,i)?'mark':opts.dim?.(r,i)?'dim':''}">${cols.map(c=>`<td class="${opts.col===c?'mark':''}">${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
const studentCols=['sid','name','major','grade'],courseCols=['course_id','course_name','credits'];
function three(){return `<div class="tiny-table"><h3>students · 节选</h3>${table(students.slice(0,3),studentCols)}</div><div class="tiny-table"><h3>courses · 节选</h3>${table(courses.slice(0,3),courseCols)}</div><div class="tiny-table"><h3>enrollments · 节选</h3>${table(enrollments.slice(0,3),['sid','course_id','score'])}</div>`}
const practice=[{q:'A．显示全部学生的学号与姓名。',hint:'来源表是 students；SELECT 后写两列，用英文逗号分隔。',sql:'SELECT sid, name\nFROM students;',result:'6 行，2 列；每名学生一条。'}, {q:'B．查出 2024 级学生的姓名与专业。',hint:'用 grade 筛选；可以筛选不在输出列表中的列。',sql:'SELECT name, major\nFROM students\nWHERE grade = 2024;',result:'林悦 / 软件工程；陈晨 / 计算机。'}, {q:'C．查出至少 3 学分的课程名与学分，按学分降序。',hint:'至少表示 >=；排序放在筛选后。',sql:'SELECT course_name, credits\nFROM courses\nWHERE credits >= 3\nORDER BY credits DESC, course_id ASC;',result:'数据库原理 4；Python程序设计 3；数据结构 3。若只按学分排序，两门 3 学分课的相对顺序未指定。'}];
let drafts=['','',''];
function widget(type,printing=false){switch(type){
case 'hero':return `<div class="hero-visual"><div class="metric">01<span style="font-size:22px;color:var(--muted)"> / 起点</span></div><h2>把数据变成<br>能回答的问题。</h2><p>一个选课系统 · 三张表 · 第一批查询<br>从零开始，把每一个结果讲明白。</p><div class="journey"><span>看懂数据</span><span>建立规则</span><span>写出查询</span></div></div>`;
case 'wide':return table([{sid:'2025001',name:'林悦',major:'计算机',course:'数据库原理',score:88},{sid:'2025001',name:'林悦',major:'计算机',course:'Python程序设计',score:92},{sid:'2025002',name:'周航',major:'数学',course:'数据库原理',score:76}],['sid','name','major','course','score'])+'<p class="caption">先用最直观的方式记录，稍后再检查重复与关联。</p>';
case 'conceptQuiz':return `<h3>小判断：MySQL 属于哪一类？</h3><div class="quiz-options">${['一条数据','数据库管理系统','整套数据库系统'].map((s,i)=>printing?`<p class="caption">${i+1}. ${s}</p>`:`<button data-quiz="${i}">${s}</button>`).join('')}</div><div class="feedback" id="feedback"></div>${printing?'<p class="caption">想一想：软件、数据集合与整个系统的范围有什么不同？</p>':''}`;
case 'flow':return `<div class="flow">${[['浏览器','用户点击“查成绩”'],['PHP 程序','处理请求，向 MySQL 发送查询'],['MySQL','执行查询，返回结果'],['PHP → 浏览器','组织结果并显示页面']].map((r,i)=>`<div class="node ${i===0?'active':''}" data-node="${i}"><strong>${r[0]}</strong><small>${r[1]}</small></div>${i<3?'<div class="arrow">↓</div>':''}`).join('')}</div><div class="controls"><button id="flowNext">下一步 →</button><button id="flowReset">重置</button></div>`;
case 'tableExplore':return `<div class="controls"><button data-explore="row">看一行</button><button data-explore="col">看一列</button><button data-explore="reset">重置</button></div><div id="exploreTable">${table(students,studentCols)}</div><p class="caption">行 = 一名学生的记录　/　列 = 所有学生的某个属性</p>`;
case 'schema':return `<pre class="code">students(\n  sid, name, major, grade\n)</pre><div id="schemaTable">${table(students.slice(0,2),studentCols)}</div><div class="controls"><button id="addInstance">模拟新增一名学生</button><button id="resetInstance">重置</button></div><p class="caption">新增记录后列名保持不变：实例变化，模式未变。</p>`;
case 'keys':return `<div class="controls"><button data-key="name">按姓名“林悦”定位</button><button data-key="sid">按学号 2025001 定位</button><button data-key="reset">重置</button></div><div id="keysTable">${table(students,studentCols)}</div><p class="caption" id="keyCaption">业务规则要求唯一；不能只看当前样本有没有重复。</p>`;
case 'split':return `<div class="controls"><button id="splitToggle">切换：拆分前 / 拆分后</button></div><div id="splitView">${printing?three():widget('wide')}</div>`;
case 'threeTables':return three();
case 'integrity':return `<h3>哪一种规则在起作用？</h3><div class="quiz-options">${['已有学号再新增一名学生','给不存在的学生录入选课','输入成绩 120'].map((s,i)=>printing?`<p class="caption">${i+1}. ${s}</p>`:`<button data-rule="${i}">${i+1}. ${s}</button>`).join('')}</div><div class="feedback" id="ruleFeedback"></div>`;
case 'levels':return `<div class="level"><strong>外模式</strong><small>学生视图 / 教师视图</small></div><div class="arrow">外模式／模式映像 · 逻辑数据独立性</div><div class="level"><strong>模式</strong><small>全局逻辑结构与约束</small></div><div class="arrow">模式／内模式映像 · 物理数据独立性</div><div class="level"><strong>内模式</strong><small>记录、文件、索引等存储组织</small></div>`;
case 'queryAll':return table(students,studentCols)+'<p class="caption">结果 6 行 × 4 列。</p>';
case 'queryCols':return table(students,['name','major'])+'<p class="caption">结果 6 行 × 2 列；原表不变。</p>';
case 'filter':return printing?table(students.filter(r=>r.grade===2025),['name','major'])+'<p class="caption">示例最终结果：筛选 2025 级，再输出姓名与专业，共 4 行。</p>':`<div class="controls"><label>年级 <select id="gradeChoice"><option>2025</option><option>2024</option><option>2023</option></select></label><button id="filterStep">下一步：筛行</button><button id="filterReset">重置</button></div><div id="filterTable">${table(students,studentCols)}</div><p class="caption" id="filterCaption">步骤 1 / 3 · 来源表。先预测哪些记录满足条件。</p>`;
case 'boundary':return `<div class="controls"><label>条件 <select id="boundaryChoice"><option value=">=">credits >= 3</option><option value=">">credits > 3</option><option value="<">credits < 3</option></select></label></div><div id="boundaryTable">${table(courses,courseCols,{mark:r=>r.credits>=3,dim:r=>r.credits<3})}</div><p class="caption">绿色行符合当前条件，其他行保留用于对比。</p>`;
case 'logic':return `<div class="controls"><select id="logicChoice"><option>AND</option><option>OR</option></select><span class="caption">grade = 2025　□　major = '计算机'</span></div><div id="logicTable">${table(students,studentCols,{mark:r=>r.grade===2025&&r.major==='计算机',dim:r=>!(r.grade===2025&&r.major==='计算机')})}</div><p id="logicCount" class="caption">AND：3 行符合条件。</p>`;
case 'sort':return `<div class="controls"><button data-sort="DESC">学分降序</button><button data-sort="ASC">学分升序</button></div><div id="sortTable">${table(courses,courseCols)}</div><p class="caption">学分相同时，按 course_id 升序。</p>`;
case 'practice':return printing?'<h3>独立写 SQL，并解释结果</h3><p class="caption">来源表 → 输出列 → 条件 → 排序</p><div style="height:100px;border-bottom:1px solid #ccd6d0"></div>':`<div class="practice-tabs">${practice.map((x,i)=>`<button data-practice="${i}" class="${i===0?'selected':''}">练习 ${'ABC'[i]}</button>`).join('')}</div><h3 id="practiceQ" style="margin-top:16px">${practice[0].q}</h3><textarea id="practiceDraft" aria-label="SQL 练习草稿" placeholder="在这里写 SQL 草稿"></textarea><div class="controls"><button id="practiceHint">给我一点提示</button><button id="practiceCopy">复制草稿</button></div><div id="practiceFeedback" class="feedback"></div>`;
case 'null':return table(enrollments,['sid','course_id','score'],{mark:r=>r.score===null})+'<p class="caption">NULL 与 0 分是两种不同状态。</p>';
default:return ''}}
function slideHTML(s,i,print=false,mode='student'){
 let right=(s.code?`<pre class="code">${esc(s.code)}</pre>${print?'':'<button class="copy" id="copySql">复制 SQL</button>'}`:'')+widget(s.widget,print);
 let answer=print?(mode!=='student'?`<div class="print-answer"><strong>参考答案</strong>　${esc(s.answer)}</div>`:''):`<button class="answer-button" id="revealBtn" aria-expanded="${reveal}">${reveal?'收起答案':'先思考，再看答案'} <kbd>R</kbd></button><div class="answer" id="answer" ${reveal?'':'hidden'}>${esc(s.answer)}</div>`;
 return `<div class="eyebrow"><span>${esc(s.sub)}</span><span class="tag">${s.extra?'备用':'主线'} · ${s.minutes} 分钟</span></div><h1>${esc(s.title)}</h1><div class="layout ${right?'':'single'}"><div><ul class="points">${s.points.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="question"><small>停下来，想一想</small>${esc(s.question)}</div>${answer}${s.ref?`<p class="ref">教材对应 · 第 6 版 ${esc(s.ref)}</p>`:''}</div>${right?`<div class="visual">${right}</div>`:''}</div>`;
}
function render(){let s=L.slides[page];$('#stage').innerHTML=`<section class="slide">${slideHTML(s,page)}</section>`;$('#pageNo').textContent=`${String(page+1).padStart(2,'0')} / ${L.slides.length}`;$('#bar').style.width=`${(page+1)/L.slides.length*100}%`;let before=L.slides.slice(0,page).filter(x=>!x.extra).reduce((n,x)=>n+x.minutes,0);$('#sectionLabel').textContent=s.extra?'备用练习 · 按需选讲':`建议进度 ${before}—${before+s.minutes} 分钟`;
 $('#prevBtn').disabled=page===0;$('#nextBtn').disabled=page===L.slides.length-1;document.title=`${String(page+1).padStart(2,'0')} · ${s.title} | 数据库入门`;bindWidget(s);sync();}
function sync(){try{localStorage.setItem('classroom-current-page',page)}catch{}channel?.postMessage({type:'slide',page,elapsed:seconds()})}
function go(n){page=Math.max(0,Math.min(L.slides.length-1,n));reveal=false;if(location.hash!==`#${page+1}`)location.hash=page+1;else render();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{page=Math.max(0,Math.min(L.slides.length-1,(Number(location.hash.slice(1))||1)-1));reveal=false;render()});
function on(selector,event,fn){const el=$(selector);if(el)el.addEventListener(event,fn)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制')}catch{toast('复制不可用，请手动选择代码复制')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function bindWidget(s){on('#revealBtn','click',()=>{reveal=!reveal;$('#answer').hidden=!reveal;$('#revealBtn').setAttribute('aria-expanded',reveal);$('#revealBtn').textContent=reveal?'收起答案 R':'先思考，再看答案 R'});
 document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>{$('#feedback').textContent=+b.dataset.quiz===1?'正确。MySQL 是管理数据库的软件；数据库保存数据，DBS 的范围更广。':'再想一想：MySQL 是提供管理功能的软件。';});
 let step=0;on('#flowNext','click',()=>{step=(step+1)%4;document.querySelectorAll('[data-node]').forEach((n,i)=>n.classList.toggle('active',i===step))});on('#flowReset','click',()=>{step=0;document.querySelectorAll('[data-node]').forEach((n,i)=>n.classList.toggle('active',i===0))});
 document.querySelectorAll('[data-explore]').forEach(b=>b.onclick=()=>$('#exploreTable').innerHTML=table(students,studentCols,b.dataset.explore==='row'?{mark:(_,i)=>i===0}:b.dataset.explore==='col'?{col:'major'}:{}));
 on('#addInstance','click',()=>$('#schemaTable').innerHTML=table(students.slice(0,3),studentCols,{mark:(_,i)=>i===2}));on('#resetInstance','click',()=>$('#schemaTable').innerHTML=table(students.slice(0,2),studentCols));
 document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{let type=b.dataset.key;$('#keysTable').innerHTML=table(students,studentCols,{mark:r=>type==='name'?r.name==='林悦':type==='sid'?r.sid==='2025001':false});$('#keyCaption').textContent=type==='name'?'姓名命中 2 条，不能唯一定位。':type==='sid'?'学号命中 1 条；业务规则保证唯一。':'业务规则要求唯一；不能只看样本。'});
 let split=false;on('#splitToggle','click',()=>{split=!split;$('#splitView').innerHTML=split?three():widget('wide')});
 document.querySelectorAll('[data-rule]').forEach(b=>b.onclick=()=>$('#ruleFeedback').textContent=['实体完整性：主键重复，本例应拒绝。','参照完整性：引用的学生不存在，本例应拒绝。','用户定义的完整性：违反 0—100 的成绩规则。'][+b.dataset.rule]);
 let fstep=0;function drawFilter(){const year=+$('#gradeChoice').value;$('#filterTable').innerHTML=fstep<2?table(students,studentCols,fstep?{mark:r=>r.grade===year,dim:r=>r.grade!==year}:{}):table(students.filter(r=>r.grade===year),['name','major']);$('#filterCaption').textContent=[`步骤 1 / 3 · 来源表。条件：grade = ${year}`,`步骤 2 / 3 · 筛选符合条件的行，共 ${students.filter(r=>r.grade===year).length} 行。`,`步骤 3 / 3 · 输出 name、major 两列。`][fstep];$('#filterStep').textContent=['下一步：筛行','下一步：选列','从头演示'][fstep];const code=$('.code');code.textContent=`SELECT name, major\nFROM students\nWHERE grade = ${year};`}
 on('#filterStep','click',()=>{fstep=(fstep+1)%3;drawFilter()});on('#filterReset','click',()=>{fstep=0;drawFilter()});on('#gradeChoice','change',drawFilter);
 on('#boundaryChoice','change',()=>{let op=$('#boundaryChoice').value,fn=r=>op==='>='?r.credits>=3:op==='>'?r.credits>3:r.credits<3;$('#boundaryTable').innerHTML=table(courses,courseCols,{mark:fn,dim:r=>!fn(r)});$('.code').textContent=`SELECT course_name, credits\nFROM courses\nWHERE credits ${op} 3;`});
 on('#logicChoice','change',()=>{const op=$('#logicChoice').value,fn=r=>op==='AND'?r.grade===2025&&r.major==='计算机':r.grade===2025||r.major==='计算机';$('#logicTable').innerHTML=table(students,studentCols,{mark:fn,dim:r=>!fn(r)});$('#logicCount').textContent=`${op}：${students.filter(fn).length} 行符合条件。`;$('.code').textContent=`SELECT sid, name\nFROM students\nWHERE grade = 2025\n  ${op} major = '计算机';`});
 document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{const order=b.dataset.sort;$('#sortTable').innerHTML=table([...courses].sort((a,b)=>(order==='DESC'?b.credits-a.credits:a.credits-b.credits)||a.course_id.localeCompare(b.course_id)),courseCols);$('.code').textContent=`SELECT course_id, course_name, credits\nFROM courses\nORDER BY credits ${order}, course_id ASC;`});
 let task=0;document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>{drafts[task]=$('#practiceDraft').value;task=+b.dataset.practice;$('#practiceQ').textContent=practice[task].q;$('#practiceDraft').value=drafts[task];$('#practiceFeedback').textContent='';document.querySelectorAll('[data-practice]').forEach(x=>x.classList.toggle('selected',x===b))});on('#practiceDraft','input',()=>drafts[task]=$('#practiceDraft').value);if($('#practiceDraft'))$('#practiceDraft').value=drafts[0];on('#practiceHint','click',()=>$('#practiceFeedback').textContent=practice[task].hint);on('#practiceAnswer','click',()=>$('#practiceFeedback').innerHTML=`<pre class="code">${esc(practice[task].sql)}</pre>${esc(practice[task].result)}`);on('#practiceCopy','click',()=>copy($('#practiceDraft').value));
 // Copy the current demonstration, including changes made with controls.
 if($('#copySql'))$('#copySql').onclick=()=>copy($('.code').textContent);
}
function seconds(){return elapsed+(running?(Date.now()-started)/1000:0)}
function clockText(){let v=Math.floor(seconds());return `${Math.floor(v/60).toString().padStart(2,'0')}:${(v%60).toString().padStart(2,'0')}`}
on('#timerBtn','click',()=>{if(running){elapsed=seconds();running=false}else{started=Date.now();running=true}$('#timerBtn').textContent=clockText()+(running?' 暂停':' 继续')});setInterval(()=>{if(running)$('#timerBtn').textContent=clockText()+' 暂停'},1000);
on('#prevBtn','click',()=>go(page-1));on('#nextBtn','click',()=>go(page+1));
on('#tocBtn','click',()=>{$('#tocList').innerHTML=L.slides.map((s,i)=>`<button data-goto="${i}" class="${i===page?'current':''}"><span>${String(i+1).padStart(2,'0')} ${esc(s.title)}</span><small>${s.extra?'备用 ':''}${s.minutes}′</small></button>`).join('');$('#toc').showModal();document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{$('#toc').close();go(+b.dataset.goto)})});
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());
on('#fullBtn','click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('当前窗口不支持网页全屏，可使用浏览器 F11。')}});
document.addEventListener('fullscreenchange',()=>$('#fullBtn').textContent=document.fullscreenElement?'退出全屏 F':'全屏 F');
on('#teacherBtn','click',()=>{const w=window.open('teacher.html#'+(page+1),'classroom_teacher','width=900,height=800');if(!w)toast('请允许弹出窗口，以打开独立讲稿。');else setTimeout(sync,500)});
channel&&(channel.onmessage=e=>{if(e.data.type==='goto')go(e.data.page);if(e.data.type==='request')sync()});
on('#pdfBtn','click',()=>$('#pdf').showModal());
function preparePrint(range='all',mode='student'){
 document.querySelectorAll('.print-slide,.notes-page').forEach(e=>e.remove());const selected=parseExportPages(params.get('pages')||$('#exportPages')?.value||'');const chosen=L.slides.filter((s,i)=>selected?selected.includes(i+1):(range==='all'||!s.extra));
 chosen.forEach((s,i)=>{let node=document.createElement('section');node.className='print-slide';node.innerHTML=slideHTML(s,i,true,mode)+`<div class="print-footer"><span>课堂讲义 · ${mode==='student'?'学生版':mode==='answers'?'复习版':'讲师版'}</span><span>${i+1} / ${chosen.length}</span></div>`;document.body.append(node);if(mode==='teacher'){let n=document.createElement('section');n.className='notes-page';n.innerHTML=`<div class="eyebrow">讲师备课 · 课件第 ${L.slides.indexOf(s)+1} 页 · ${s.minutes} 分钟</div><h1>${esc(s.title)}</h1><div class="teacher-note-grid ${s.answer?'with-answer':''}"><div><h3>逐字稿</h3><p>${esc(s.script||s.notes)}</p><h3>备课提示</h3><p class="teacher-tip">${esc(s.notes)}</p></div>${s.answer?`<div class="teacher-note-answer"><h3>问题与教师答案</h3><p>${esc(s.question)}</p><pre>${esc(s.answer)}</pre></div>`:''}</div>`;document.body.append(n)}});window.__printReady=true;
}
on('#printBtn','click',()=>{preparePrint($('#exportRange').value,$('#exportMode').value);$('#pdf').close();window.print()});
on('#exportBtn','click',async()=>{let status=$('#exportStatus'),btn=$('#exportBtn');let selected;try{selected=parseExportPages($('#exportPages').value)}catch(e){status.textContent=e.message;return}btn.disabled=true;status.textContent='正在排版并嵌入版权标记，通常需要十几秒…';try{const r=await fetch('http://127.0.0.1:18801/api/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({range:$('#exportRange').value,mode:$('#exportMode').value,pages:selected})});if(!r.ok)throw Error(await r.text());const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`课程_${$('#exportMode').value}_${$('#exportRange').value}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='导出完成：已包含作者、邮箱、导出编号及逐页不可见版权文字。'}catch(e){status.textContent='导出失败：'+e.message+'。请双击文件夹中的“课程_启动.cmd”启动导出服务，再重试。'}finally{btn.disabled=false}});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;const k=e.key.toLowerCase();if(e.target.tagName==='BUTTON'&&(k===' '||k==='enter'))return;if(['arrowright','pagedown',' '].includes(k)){e.preventDefault();go(page+1)}if(['arrowleft','pageup'].includes(k)){e.preventDefault();go(page-1)}if(k==='home')go(0);if(k==='end')go(L.slides.length-1);if(k==='f')$('#fullBtn').click();if(k==='g')$('#tocBtn').click();if(k==='r')$('#revealBtn')?.click();if(k==='t')$('#teacherBtn').click()});
window.addEventListener('beforeprint',()=>{if(!document.querySelector('.print-slide'))preparePrint()});
render();if(params.has('print'))preparePrint(params.get('range')||'core',params.get('mode')||'student');
